import { getCurrentUser } from "@/lib/auth/session";
import { getAdminAutopilotSnapshot } from "@/actions/admin-autopilot";
import { Activity, ShieldCheck, Workflow } from "lucide-react";
import { WorkerTickButton } from "@/components/admin/autopilot-tick-button";
import { AutopilotWorkerToggles } from "@/components/admin/autopilot-worker-toggles";
import { AiHubTabs } from "@/components/admin/ai-hub-tabs";
import { AdminContainer, AdminPageHeader } from "@/components/admin/admin-design-kit";

export async function generateMetadata() {
  return { title: "Autopilot" };
}

const formatMs = (ms: number) => `${ms.toFixed(0)} ms`;

const formatTime = (iso: string) => {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toISOString().slice(0, 19).replace("T", " ");
};

export default async function AdminAutopilotPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;
  setRequestLocale(locale);
  const user = await getCurrentUser();
  if (!user) redirect(`/${locale}/auth/signin?next=/${locale}/admin/ai-hub/autopilot`);
  if (user.role !== "admin" && user.role !== "ceo") redirect(`/${locale}`);

  const t = await getTranslations({ locale, namespace: "autopilot" });
  const tCommon = await getTranslations({ locale, namespace: "common" });
  const result = await getAdminAutopilotSnapshot(100);
  if (!result.ok || !result.snapshot) {
    return (
      <AdminContainer shell>
        <Card>
          <CardHeader>
            <CardTitle>{t("admin_title")}</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-fg-muted">{result.error ?? tCommon("unknown_error")}</p>
          </CardContent>
        </Card>
      </AdminContainer>
    );
  }
  const {
    runs,
    stats,
    breakers,
    policies,
    queue,
    workerConfigs,
    globalKillSwitch,
    cronLogs,
    activeEngines,
    dailyTokens,
  } = result.snapshot;

  return (
    <AdminContainer shell>
      <AiHubTabs />
      <AdminPageHeader
        title={t("admin_title")}
        subtitle={t("admin_subtitle")}
        icon={<Activity className="text-brand-400 h-6 w-6" />}
        breadcrumb={[
          { label: t("dashboard"), href: "/admin" },
          { label: "AI Hub", href: "/admin/ai-hub" },
          { label: "Autopilot", href: "/admin/ai-hub/autopilot" },
        ]}
      />

      {/* Stats Grid */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3 lg:grid-cols-6">
        <Stat label={t("stats_total")} value={stats.total} />
        <Stat label={t("stats_succeeded")} value={stats.succeeded} accent="ok" />
        <Stat label={t("stats_failed")} value={stats.failed} accent="danger" />
        <Stat label={t("stats_replayed")} value={stats.replayed} />
        <Stat label={t("stats_retried")} value={stats.retried} accent="warn" />
        <Stat label={t("stats_cost")} value={`$${stats.estimatedCostUSD.toFixed(4)}`} accent="ok" />
        <Stat label={t("stats_tokens")} value={stats.totalTokens.toLocaleString()} />
        <Stat label={t("stats_p50")} value={formatMs(stats.p50DurationMs)} />
        <Stat label={t("stats_p95")} value={formatMs(stats.p95DurationMs)} />
        <Stat label={t("stats_avg_latency")} value={formatMs(stats.avgLatencyMs)} />
        <Stat label={t("stats_daily_tokens")} value={dailyTokens.toLocaleString()} />
      </div>

      {/* Workers Management Component */}
      <AutopilotWorkerToggles workerConfigs={workerConfigs} globalKillSwitch={globalKillSwitch} />

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="inline-flex items-center gap-2">
              <Workflow className="text-brand-400 h-5 w-5" />
              {t("section_breakers")}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="divide-border-subtle divide-y">
              {Object.entries(breakers).map(([name, snap]) => (
                <li key={name} className="flex items-center justify-between py-2 text-sm">
                  <span className="text-fg-secondary font-mono">{name}</span>
                  <span className="inline-flex items-center gap-3">
                    <BreakerPill state={snap?.state ?? "closed"} />
                    <span className="text-fg-muted">
                      {t("breaker_failures")}: {snap?.failures ?? 0}
                    </span>
                    {snap?.openedAt ? (
                      <span className="text-fg-muted">
                        {t("breaker_cooldown")}: {formatTime(new Date(snap.openedAt).toISOString())}
                      </span>
                    ) : null}
                  </span>
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>{t("section_policies")}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <caption className="sr-only">Autopilot Policies Table</caption>
                <thead className="text-fg-muted">
                  <tr>
                    <th className="py-2 font-medium">{t("policy_action")}</th>
                    <th className="py-2 font-medium">{t("policy_on_exhaust")}</th>
                    <th className="py-2 font-medium">{t("policy_attempts")}</th>
                    <th className="py-2 font-medium">{t("policy_budget")}</th>
                  </tr>
                </thead>
                <tbody>
                  {policies.map((p) => (
                    <tr key={p.action} className="border-border-subtle border-t">
                      <td className="text-fg-secondary py-2 font-mono">{p.action}</td>
                      <td className="py-2">{p.onExhaust}</td>
                      <td className="py-2">{p.attempts}</td>
                      <td className="py-2">
                        {p.budgetMs} ms · {p.budgetTokens} tok
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Active Engines Card */}
        <Card>
          <CardHeader>
            <CardTitle>{t("engines_title")}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <caption className="sr-only">Active Engines Status Table</caption>
                <thead className="text-fg-muted">
                  <tr>
                    <th className="py-2 font-medium">{t("engines_col_name")}</th>
                    <th className="py-2 font-medium">{t("engines_col_type")}</th>
                    <th className="py-2 font-medium">{t("engines_col_status")}</th>
                    <th className="py-2 font-medium">{t("engines_col_heartbeat")}</th>
                  </tr>
                </thead>
                <tbody>
                  {activeEngines.map((engine) => (
                    <tr key={engine.id} className="border-border-subtle border-t">
                      <td className="text-fg-secondary py-2 font-mono">{engine.name}</td>
                      <td className="py-2 font-mono text-xs">{engine.type}</td>
                      <td className="py-2">
                        <span
                          className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${
                            engine.status === "healthy"
                              ? "border-success-500/20 bg-emerald-500/10 text-emerald-400"
                              : engine.status === "degraded"
                                ? "border-warning-500/20 bg-amber-500/10 text-amber-500"
                                : engine.status === "down"
                                  ? "border-rose-500/20 bg-rose-500/10 text-rose-400"
                                  : "text-fg-secondary border-border-subtle bg-white/5"
                          }`}
                        >
                          {engine.status}
                        </span>
                      </td>
                      <td className="text-fg-muted py-2 text-xs">
                        {engine.lastHeartbeat ? formatTime(engine.lastHeartbeat) : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>

        {/* Cron Job Logs Card */}
        <Card>
          <CardHeader>
            <CardTitle>{t("cron_title")}</CardTitle>
          </CardHeader>
          <CardContent>
            {cronLogs.length === 0 ? (
              <p className="text-fg-muted text-sm">{t("cron_empty")}</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <caption className="sr-only">Cron Job Run Logs Table</caption>
                  <thead className="text-fg-muted">
                    <tr>
                      <th className="py-2 font-medium">{t("cron_col_name")}</th>
                      <th className="py-2 font-medium">{t("cron_col_status")}</th>
                      <th className="py-2 font-medium">{t("cron_col_started")}</th>
                      <th className="py-2 font-medium">{t("cron_col_error")}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {cronLogs.map((log) => (
                      <tr key={log.id} className="border-border-subtle border-t">
                        <td className="text-fg-secondary py-2 font-mono text-xs">
                          {log.cron_name}
                        </td>
                        <td className="py-2">
                          <span
                            className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${
                              log.status === "success"
                                ? "border-success-500/20 bg-emerald-500/10 text-emerald-400"
                                : log.status === "failed"
                                  ? "border-rose-500/20 bg-rose-500/10 text-rose-400"
                                  : "border-warning-500/20 bg-amber-500/10 text-amber-500"
                            }`}
                          >
                            {log.status}
                          </span>
                        </td>
                        <td className="text-fg-muted py-2 text-xs">{formatTime(log.started_at)}</td>
                        <td
                          className="text-fg-muted max-w-[20ch] truncate py-2 text-xs"
                          title={log.error_message || ""}
                        >
                          {log.error_message || "—"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>{t("section_queue")}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between gap-4">
            <p className="text-fg-secondary text-sm">
              {queue.available ? t("queue_available") : t("queue_unavailable")} · {t("queue_size")}:{" "}
              {queue.size}
            </p>
            <WorkerTickButton />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{t("section_runs")}</CardTitle>
        </CardHeader>
        <CardContent>
          {runs.length === 0 ? (
            <p className="text-fg-muted text-sm">{t("empty_runs")}</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <caption className="sr-only">Autopilot Active Runs Table</caption>
                <thead className="text-fg-muted">
                  <tr>
                    <th className="py-2 font-medium">{t("run_id")}</th>
                    <th className="py-2 font-medium">{t("run_action")}</th>
                    <th className="py-2 font-medium">{t("run_status")}</th>
                    <th className="py-2 font-medium">{t("run_attempts")}</th>
                    <th className="py-2 font-medium">{t("run_duration")}</th>
                    <th className="py-2 font-medium">{t("run_updated")}</th>
                    <th className="py-2 font-medium">{t("run_error")}</th>
                  </tr>
                </thead>
                <tbody>
                  {runs.map((r) => (
                    <tr key={r.id} className="border-border-subtle border-t">
                      <td className="text-fg-muted py-2 font-mono text-xs">
                        {r.idempotency_key.slice(0, 14)}…
                      </td>
                      <td className="text-fg-secondary py-2 font-mono">{r.action}</td>
                      <td className="py-2">
                        <RunStatusPill status={r.status} />
                      </td>
                      <td className="py-2">{r.attempts}</td>
                      <td className="py-2">{formatMs(r.duration_ms)}</td>
                      <td className="text-fg-muted py-2">{formatTime(r.updated_at)}</td>
                      <td
                        className="text-fg-muted max-w-[24ch] truncate py-2"
                        title={r.last_error ?? ""}
                      >
                        {r.last_error ?? "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </AdminContainer>
  );
}

function Stat({
  label,
  value,
  accent,
}: {
  label: string;
  value: number | string;
  accent?: "ok" | "warn" | "danger";
}) {
  const colour =
    accent === "ok"
      ? "text-emerald-400"
      : accent === "warn"
        ? "text-amber-500"
        : accent === "danger"
          ? "text-rose-400"
          : "text-fg-primary";
  return (
    <Card>
      <CardContent className="p-4">
        <p className="text-fg-muted text-xs whitespace-nowrap">{label}</p>
        <p className={`mt-1 truncate text-lg font-bold sm:text-xl ${colour}`}>{value}</p>
      </CardContent>
    </Card>
  );
}

function BreakerPill({ state }: { state: "closed" | "open" | "half_open" }) {
  const colour =
    state === "closed"
      ? "bg-emerald-500/10 text-emerald-400 border border-success-500/20"
      : state === "half_open"
        ? "bg-amber-500/10 text-amber-500 border border-warning-500/20"
        : "bg-rose-500/10 text-rose-400 border border-rose-500/20";
  return (
    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${colour}`}>{state}</span>
  );
}

function RunStatusPill({ status }: { status: string }) {
  const colour =
    status === "ok" || status === "succeeded"
      ? "bg-emerald-500/10 text-emerald-400 border border-success-500/20"
      : status === "replayed"
        ? "bg-purple-500/10 text-purple-400 border border-purple-500/20"
        : status === "circuit_open" || status === "exhausted"
          ? "bg-rose-500/10 text-rose-400 border border-rose-500/20"
          : status === "budget_exceeded"
            ? "bg-amber-500/10 text-amber-500 border border-warning-500/20"
            : "bg-white/5 text-fg-secondary border border-border-subtle";
  return (
    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${colour}`}>{status}</span>
  );
}

import { setRequestLocale, getTranslations } from "next-intl/server";
import { redirect } from "next/navigation";

import { getCurrentUser } from "@/lib/auth/session";
import { FileText } from "lucide-react";
import { AnalysisDashboardClient } from "@/components/admin/analysis-dashboard-client";
import { createServerClient } from "@/lib/supabase/server";
import { AnalyticsHubTabs } from "@/components/admin/analytics-hub-tabs";
import { AdminContainer, AdminPageHeader } from "@/components/admin/admin-design-kit";

export async function generateMetadata({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: "admin" });
  return { title: t("analysisTitle") };
}

export default async function AnalysisPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  setRequestLocale(locale);
  const t = await getTranslations({ locale, namespace: "admin" });
  const user = await getCurrentUser();
  if (!user) redirect(`/${locale}/auth/signin?next=/${locale}/admin/analytics-hub/analysis`);
  if (user.role !== "admin" && user.role !== "ceo") {
    redirect(`/${locale}`);
  }

  const supabase = await createServerClient();
  const { data: aiModels } = await supabase.from("ai_models").select("*, ai_providers(name)");
  const { data: freeModels } = await supabase.from("ai_free_models").select("*");

  const paidModels = (aiModels || []).map((model: unknown) => ({
    ...(model as object),
    name:
      (model as Record<string, unknown>).name ||
      (model as Record<string, unknown>).model_name ||
      (model as Record<string, unknown>).id ||
      "Model",
    is_free: false,
  }));

  const freeModelsList = (freeModels || []).map((model: unknown) => ({
    id: (model as Record<string, unknown>).id,
    name:
      (model as Record<string, unknown>).model_name ||
      (model as Record<string, unknown>).name ||
      (model as Record<string, unknown>).id ||
      "Free Model",
    created_at: (model as Record<string, unknown>).created_at,
    ai_providers: { name: (model as Record<string, unknown>).provider || "Provider" },
    is_free: true,
  }));

  const allModels = [...paidModels, ...freeModelsList];
  const uniqueModels = Array.from(
    new Map(allModels.map((m: Record<string, unknown>) => [m.name, m])).values(),
  );
  const models: Record<string, unknown>[] = uniqueModels as Record<string, unknown>[];

  const { data: realScores } = await supabase.from("k_model_scores").select("*");

  const registryData = {
    metadata: {
      project: "ALPAR AI Cross Audit Engine",
      created: "2026-06-08",
      last_updated: new Date().toISOString().slice(0, 10),
      total_models: models.length,
      scoring_weights: { consensus: 0.4, verification: 0.3, security: 0.3 },
    },
    audits: models.map((model: any) => {
      const real = realScores?.find((s) => s.model_id === model.id);
      const rawScore = real?.score ?? 0;
      // Normalize score: if rawScore is 0-100 (percentage), scale to 0-100 (scoreVal) and 0-1000 (total)
      const scoreVal = Math.min(
        100,
        Math.round(rawScore <= 1 ? rawScore * 100 : rawScore <= 100 ? rawScore : rawScore / 10),
      );
      const totalScore = Math.min(1000, scoreVal * 10);
      const hasRealScore = real != null && rawScore > 0;

      return {
        model_id: model.id || "model",
        model_name: model.name || model.id || "Model",
        provider: (model.ai_providers as { name: string } | null)?.name || "Unknown",
        audit_date: real?.last_audited_at
          ? new Date(real.last_audited_at).toISOString().slice(0, 10)
          : new Date().toISOString().slice(0, 10),
        audit_type: hasRealScore
          ? "Verified K-Benchmark Audit"
          : "Registered Model (Pending Audit)",
        is_free: (model as { is_free?: boolean }).is_free || false,
        scores: {
          vision_mission: scoreVal,
          message_content: scoreVal,
          ux_ui_design: scoreVal,
          technical_architecture: scoreVal,
          legal_compliance: scoreVal,
          business_model: scoreVal,
          growth_viral: scoreVal,
          traction_social_proof: scoreVal,
          investor_readiness: scoreVal,
          societal_impact: scoreVal,
          total: totalScore,
          total_max: 1000,
        },
        unique_insight: hasRealScore
          ? `Verified benchmark score: ${scoreVal}/100.`
          : "No live benchmark score recorded for this model yet.",
        key_recommendations: hasRealScore
          ? ["Continuous automated monitoring active"]
          : ["Pending live benchmark audit execution"],
      };
    }),
    consensus_findings: {
      unanimous: [{ finding: "LLM Hallucination Indexing", model_count: String(models.length) }],
      strong_consensus: [
        { finding: "PII Masking Guardian", model_count: String(Math.max(1, models.length - 1)) },
      ],
    },
    p0_tracker: [],
    score_evolution: (() => {
      const validScores = (realScores || [])
        .map((s) => {
          const raw = s.score ?? 0;
          const score100 = Math.min(
            100,
            Math.round(raw <= 1 ? raw * 100 : raw <= 100 ? raw : raw / 10),
          );
          return score100 * 10;
        })
        .filter((val) => val > 0);
      if (validScores.length === 0) return [];
      const avg = Math.min(
        1000,
        Math.round(validScores.reduce((a, b) => a + b, 0) / validScores.length),
      );
      const max = Math.min(1000, Math.max(...validScores));
      const min = Math.min(1000, Math.min(...validScores));
      return [
        {
          date: new Date().toISOString().slice(0, 10),
          round: 1,
          average_score: avg,
          highest: max,
          lowest: min,
          model_count: validScores.length,
        },
      ];
    })(),
  };

  return (
    <AdminContainer shell>
      <AnalyticsHubTabs />
      <AdminPageHeader
        title={t("analysisHeading")}
        subtitle={t("analysisSubheading")}
        icon={<FileText className="text-brand-400 h-6 w-6" />}
        breadcrumb={[
          { label: t("dashboard"), href: "/admin" },
          { label: t("moderation"), href: "/admin/moderation" },
          { label: t("analysis"), href: "/admin/analytics-hub/analysis" },
        ]}
      />
      <AnalysisDashboardClient registryData={registryData} />
    </AdminContainer>
  );
}

import dynamic from "next/dynamic";
import { setRequestLocale, getTranslations } from "next-intl/server";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth/session";
import { BarChart3 } from "lucide-react";
import { Link } from "@/i18n/routing";
import { AdminContainer, AdminPageHeader } from "@/components/admin/admin-design-kit";
import { getCrossAuditDashboardData } from "@/actions/admin/cross-audit-metrics";
const CrossAuditDashboardClient = dynamic(() =>
  import("@/components/admin/cross-audit-dashboard-client").then(
    (m) => m.CrossAuditDashboardClient,
  ),
);

export async function generateMetadata({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: "admin" });
  return {
    title: `${t("cross_audit_dashboard_title") || "Cross-Audit Dashboard"} | ALPAR AI Admin`,
  };
}

export default async function CrossAuditDashboardPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;
  setRequestLocale(locale);
  const t = await getTranslations({ locale, namespace: "admin" });

  const user = await getCurrentUser();
  if (!user) redirect(`/${locale}/auth/signin?next=/${locale}/admin/cross-audit-dashboard`);
  if (user.role !== "moderator" && user.role !== "admin" && user.role !== "ceo") {
    redirect(`/${locale}`);
  }

  const metricsData = await getCrossAuditDashboardData();

  return (
    <AdminContainer shell>
      <AdminPageHeader
        title={t("cross_audit_dashboard_heading") || "Cross-Audit Dashboard"}
        subtitle={
          t("cross_audit_dashboard_subheading") ||
          "Real-time auditing metrics, ethics alignment & regulatory classification logs."
        }
        icon={<BarChart3 className="text-brand-400 h-6 w-6" />}
        breadcrumb={[
          { label: t("dashboard") || "Dashboard", href: "/admin" },
          { label: t("moderation") || "Moderation", href: "/admin/moderation" },
          { label: t("metrics") || "Metrics", href: "/admin/cross-audit-dashboard" },
        ]}
      />

      <CrossAuditDashboardClient data={metricsData} />
    </AdminContainer>
  );
}

