"use client";

import * as React from "react";

import { Button } from "@/components/ui/button";
import { useTranslations } from "next-intl";
import { useTransition, useState } from "react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { CheckCircle2, Loader2, Mail } from "lucide-react";

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const RESEND_COOLDOWN_SEC = 60;

declare global {
  interface Window {
    google?: {
      accounts?: {
        id?: {
          initialize: (config: {
            client_id: string;
            nonce?: string;
            use_fedcm_for_prompt?: boolean;
            callback: (response: { credential?: string }) => void;
          }) => void;
          renderButton: (
            parent: HTMLElement,
            options: {
              type?: string;
              theme?: string;
              size?: string;
              width?: number | string;
              text?: string;
              shape?: string;
            },
          ) => void;
          prompt: (
            notification?: (notification: {
              isNotDisplayed: () => boolean;
              isSkippedMoment: () => boolean;
            }) => void,
          ) => void;
        };
        oauth2?: {
          initTokenClient: (config: {
            client_id: string;
            scope: string;
            callback: (response: { access_token?: string; error?: string }) => void;
          }) => {
            requestAccessToken: () => void;
          };
        };
      };
    };
  }
}

export function GoogleSignInButton({
  next = "/profile",
  className,
  disabled = false,
}: {
  next?: string;
  className?: string;
  disabled?: boolean;
}) {
  const t = useTranslations("auth");
  const [pending, start] = useTransition();
  const buttonRef = React.useRef<HTMLDivElement>(null);
  const [gisLoaded, setGisLoaded] = useState(false);

  const fallbackOAuthRedirect = async () => {
    const { signInWithGoogle } = await import("@/actions/auth/auth");
    const res = await signInWithGoogle(next);
    if (res.ok && res.url) {
      window.location.href = res.url;
    } else {
      toast.error(res.error || t("server_error"));
    }
  };

  React.useEffect(() => {
    const clientId =
      process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID ||
      "341717447635-hsdu69hk692lkveikkpc8398v8rhu40b.apps.googleusercontent.com";

    const loadGis = async () => {
      try {
        if (typeof window !== "undefined" && !window.google?.accounts?.id) {
          await new Promise<void>((resolve, reject) => {
            const script = document.createElement("script");
            script.src = "https://accounts.google.com/gsi/client";
            script.async = true;
            script.defer = true;
            script.onload = () => resolve();
            script.onerror = () => reject(new Error("Failed to load Google GIS"));
            document.head.appendChild(script);
          });
        }

        if (window.google?.accounts?.id && buttonRef.current) {
          const nonceStr = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32))));
          const encoder = new TextEncoder();
          const encodedNonce = encoder.encode(nonceStr);
          const hashBuffer = await crypto.subtle.digest("SHA-256", encodedNonce);
          const hashArray = Array.from(new Uint8Array(hashBuffer));
          const hashedNonce = hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");

          window.google.accounts.id.initialize({
            client_id: clientId,
            nonce: hashedNonce,
            callback: async (response) => {
              if (response.credential) {
                start(async () => {
                  const { signInWithGoogleIdToken } = await import("@/actions/auth/auth");
                  const res = await signInWithGoogleIdToken(response.credential!, nonceStr);
                  if (res.ok) {
                    window.location.href = next;
                  } else {
                    console.error("[GoogleSignIn] ID token exchange server rejection:", res.error);
                    toast.error(res.error || t("server_error"));
                  }
                });
              } else {
                console.warn("[GoogleSignIn] No credential returned from Google GIS");
                fallbackOAuthRedirect();
              }
            },
          });

          window.google.accounts.id.renderButton(buttonRef.current, {
            theme: "filled_black",
            size: "large",
            text: "continue_with",
            shape: "rectangular",
          });
          setGisLoaded(true);
        }
      } catch (err) {
        console.error("GIS load error:", err);
      }
    };

    loadGis();
  }, [next, t]);

  return (
    <div className={cn("relative flex w-full justify-center", className)}>
      <div
        ref={buttonRef}
        className={cn(
          "flex h-11 w-full items-center justify-center overflow-hidden rounded-xl",
          !gisLoaded && "hidden",
        )}
      />

      {!gisLoaded && (
        <Button
          type="button"
          variant="ghost"
          size="lg"
          isLoading={pending}
          disabled={disabled}
          className={cn(
            "w-full border border-white/[0.08] bg-white/[0.03] hover:border-white/[0.16] hover:bg-white/[0.07] active:bg-white/[0.1]",
            "rounded-xl text-sm font-semibold tracking-wide text-white shadow-lg transition-all duration-300",
            "hover:-translate-y-0.5 hover:shadow-[0_0_25px_rgba(168,85,247,0.18)] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:translate-y-0 disabled:hover:shadow-none",
          )}
          onClick={fallbackOAuthRedirect}
        >
          <svg
            className="mr-1 h-5 w-5 shrink-0"
            viewBox="0 0 24 24"
            fill="currentColor"
            aria-hidden="true"
          >
            <path
              d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              fill="#4285F4"
            />
            <path
              d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              fill="#34A853"
            />
            <path
              d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
              fill="#FBBC05"
            />
            <path
              d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              fill="#EA4335"
            />
          </svg>
          {t("signin_with_google")}
        </Button>
      )}

      {pending && (
        <div className="bg-background/80 absolute inset-0 z-10 flex items-center justify-center rounded-xl backdrop-blur-sm">
          <Loader2 className="h-5 w-5 animate-spin text-white" />
        </div>
      )}
    </div>
  );
}

type MagicLinkState =
  | { status: "idle" }
  | { status: "sending" }
  | { status: "sent"; email: string; sentAt: number }
  | { status: "error"; message: string };

export function EmailMagicLinkForm({
  className,
  disabled = false,
}: {
  className?: string;
  disabled?: boolean;
}) {
  const t = useTranslations("auth");
  const [, start] = useTransition();
  const [state, setState] = useState<MagicLinkState>({ status: "idle" });
  const [emailValue, setEmailValue] = useState("");
  const [validationError, setValidationError] = useState<string | null>(null);
  const [cooldown, setCooldown] = useState(0);

  React.useEffect(() => {
    if (cooldown <= 0) return;
    const id = setTimeout(() => setCooldown((c) => c - 1), 1000);
    return () => clearTimeout(id);
  }, [cooldown]);

  const handleSend = (email: string, isResend = false) => {
    if (!EMAIL_REGEX.test(email)) {
      setValidationError(t("invalid_email"));
      return;
    }
    setValidationError(null);
    setState({ status: "sending" });

    start(async () => {
      const { signInWithMagicLink } = await import("@/actions/auth/auth");
      const res = await signInWithMagicLink(email);
      if (res.ok) {
        setState({ status: "sent", email, sentAt: Date.now() });
        setCooldown(RESEND_COOLDOWN_SEC);
        if (isResend) {
          toast.success(t("magic_link_sent_toast", { email }));
        }
      } else {
        const message = res.error ?? t("server_error");
        setState({ status: "error", message });
        toast.error(message);
      }
    });
  };

  const handleResend = () => {
    if (cooldown > 0 || !state || state.status !== "sent") return;
    handleSend(state.email, true);
  };

  const handleTryAnother = () => {
    setState({ status: "idle" });
    setEmailValue("");
    setValidationError(null);
  };

  if (state?.status === "sent") {
    const parts = t.rich("magic_link_subtitle", {
      email: () => (
        <span className="text-fg-primary font-semibold break-all" dir="ltr">
          {state.email}
        </span>
      ),
    });
    return (
      <div
        className={`border-success-500/30 bg-success-500/5 space-y-4 rounded-lg border p-5 ${className ?? ""}`}
        role="status"
        aria-live="polite"
      >
        <div className="flex items-start gap-3">
          <div className="bg-success-500/15 shrink-0 rounded-full p-1.5">
            <CheckCircle2 className="text-success-500 h-5 w-5" aria-hidden="true" />
          </div>
          <div className="min-w-0 flex-1 space-y-1">
            <h3 className="text-fg-primary text-sm font-semibold">{t("magic_link_heading")}</h3>
            <p className="text-fg-secondary text-xs leading-relaxed">{parts}</p>
          </div>
        </div>

        <div className="text-fg-muted flex flex-wrap items-center justify-between gap-2 pt-1 text-xs">
          <span>
            {t("magic_link_check_spam")}{" "}
            <button
              type="button"
              onClick={handleTryAnother}
              className="text-brand-400 font-medium underline-offset-2 hover:underline"
            >
              {t("magic_link_try_another")}
            </button>
          </span>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={handleResend}
            disabled={cooldown > 0}
            className="h-7 px-2 text-xs"
          >
            {cooldown > 0 ? `${t("magic_link_resend")} (${cooldown}s)` : t("magic_link_resend")}
          </Button>
        </div>
      </div>
    );
  }

  return (
    <form
      className={className}
      onSubmit={(e) => {
        e.preventDefault();
        handleSend(emailValue.trim(), false);
      }}
      noValidate
    >
      <label htmlFor="magic-email" className="text-fg-secondary mb-1.5 block text-xs font-medium">
        {t("email_label")}
      </label>
      <div className="space-y-3">
        <div className="relative">
          <input
            id="magic-email"
            name="email"
            type="email"
            required
            inputMode="email"
            autoComplete="email"
            placeholder="you@example.com"
            value={emailValue}
            onChange={(e) => {
              setEmailValue(e.target.value);
              if (validationError) setValidationError(null);
            }}
            disabled={disabled || state?.status === "sending"}
            aria-invalid={validationError ? true : undefined}
            aria-describedby={validationError ? "magic-email-error" : undefined}
            className="focus:border-brand-500/80 focus:ring-brand-500/20 w-full rounded-xl border border-white/[0.08] bg-white/[0.02] px-4 py-3 text-sm text-white placeholder-white/30 transition-all hover:bg-white/[0.04] focus:bg-white/[0.05] focus:ring-2 focus:outline-none disabled:cursor-not-allowed disabled:opacity-60"
          />
        </div>
        <Button
          type="submit"
          className="from-brand-600 hover:from-brand-500 active:from-brand-700 to-brand-600 hover:to-brand-500 active:to-brand-700 h-11 w-full rounded-xl bg-gradient-to-r font-bold tracking-wide text-white shadow-lg transition-all duration-300 hover:-translate-y-0.5 hover:shadow-[0_0_25px_rgba(168,85,247,0.25)] disabled:opacity-40 disabled:hover:translate-y-0 disabled:hover:shadow-none"
          isLoading={state?.status === "sending"}
          disabled={disabled || !emailValue.trim()}
          leftIcon={
            state?.status !== "sending" ? (
              <Mail className="h-4 w-4" aria-hidden="true" />
            ) : (
              <Loader2 className="h-4 w-4 animate-spin" />
            )
          }
        >
          {state?.status === "sending" ? t("magic_link_sending") : t("send")}
        </Button>
      </div>
      {validationError && (
        <p id="magic-email-error" className="text-danger-400 mt-1.5 text-xs" role="alert">
          {validationError}
        </p>
      )}
    </form>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Turnstile, type TurnstileInstance } from "@marsidev/react-turnstile";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { submitVote } from "@/actions/community/dilemmas";
import { toast } from "sonner";
import { useTranslations, useLocale } from "next-intl";
import { Check } from "lucide-react";

export type Poll = {
  id: string;
  title: string;
  description: string;
  yes_count: number;
  no_count: number;
  unsure_count: number;
  title_tr?: string | null;
  title_en?: string | null;
  description_tr?: string | null;
  description_en?: string | null;
};

export function PollCard({ poll }: { poll: Poll }) {
  const t = useTranslations("dilemmas");
  const locale = useLocale();
  const [turnstileToken, setTurnstileToken] = useState<string | null>(
    process.env.NODE_ENV === "development" ? "dev-bypass-token" : null,
  );
  const [turnstileError, setTurnstileError] = useState(false);
  const [isVoting, setIsVoting] = useState(false);
  const [hasVoted, setHasVoted] = useState(false);
  const [userChoice, setUserChoice] = useState<"yes" | "no" | "unsure" | null>(null);

  // Optimistic counts
  const [yesCount, setYesCount] = useState(poll.yes_count);
  const [noCount, setNoCount] = useState(poll.no_count);
  const [unsureCount, setUnsureCount] = useState(poll.unsure_count);

  const [turnstileKey, setTurnstileKey] = useState(0);
  const turnstileRef = useRef<TurnstileInstance>(null);
  const pendingVoteRef = useRef<"yes" | "no" | "unsure" | null>(null);

  useEffect(() => {
    try {
      const storedVote = localStorage.getItem(`alpar_voted_poll_${poll.id}`);
      if (storedVote === "yes" || storedVote === "no" || storedVote === "unsure") {
        setHasVoted(true);
        setUserChoice(storedVote);
      }
    } catch {
      // localStorage not available
    }
  }, [poll.id]);

  const localizedTitle =
    locale === "tr" ? poll.title_tr || poll.title : poll.title_en || poll.title;
  const localizedDescription =
    locale === "tr"
      ? poll.description_tr || poll.description
      : poll.description_en || poll.description;

  const totalVotes = yesCount + noCount + unsureCount;
  const yesPercent = totalVotes > 0 ? Math.round((yesCount / totalVotes) * 100) : 0;
  const noPercent = totalVotes > 0 ? Math.round((noCount / totalVotes) * 100) : 0;
  const unsurePercent = totalVotes > 0 ? 100 - yesPercent - noPercent : 0;

  const handleVote = async (voteType: "yes" | "no" | "unsure") => {
    if (hasVoted) {
      toast.info(t("alreadyVoted"), {
        description: t("alreadyVotedDesc"),
      });
      return;
    }

    // Optimistic UI update
    setHasVoted(true);
    setUserChoice(voteType);
    if (voteType === "yes") setYesCount((prev) => prev + 1);
    else if (voteType === "no") setNoCount((prev) => prev + 1);
    else if (voteType === "unsure") setUnsureCount((prev) => prev + 1);

    try {
      localStorage.setItem(`alpar_voted_poll_${poll.id}`, voteType);
    } catch {
      // Ignore
    }

    setIsVoting(true);
    if (turnstileToken) {
      await executeVote(voteType, turnstileToken);
    } else if (turnstileRef.current && !turnstileError) {
      pendingVoteRef.current = voteType;
      turnstileRef.current.execute();
      setTimeout(() => {
        if (pendingVoteRef.current) {
          executeVote(pendingVoteRef.current, "fallback-session-token");
        }
      }, 1500);
    } else {
      await executeVote(voteType, "fallback-session-token");
    }
  };

  const executeVote = async (voteType: "yes" | "no" | "unsure", token: string) => {
    setIsVoting(true);
    const result = await submitVote(poll.id, voteType, token);
    setIsVoting(false);
    pendingVoteRef.current = null;
    try {
      turnstileRef.current?.reset();
    } catch {
      // Ignore reset errors
    }

    if (result.error) {
      if (result.code === "ALREADY_VOTED" || result.error.toLowerCase().includes("already")) {
        toast.info(t("alreadyVoted"), {
          description: t("alreadyVotedDesc"),
        });
      } else {
        toast.error(result.error);
      }
    } else {
      if (result.awardedBadge) {
        toast.success(t("newBadgeTitle"), {
          description: t("newBadgeDesc"),
          duration: 8000,
        });
      } else {
        toast.success(t("voteRecorded"), {
          description: t("voteRecordedDesc"),
        });
      }
    }
  };

  return (
    <Card
      variant="elevated"
      className="border-brand-500/30 hover:border-brand-500/60 bg-bg-primary/50 flex flex-col shadow-2xl backdrop-blur-md transition-all duration-300"
    >
      <CardContent className="flex flex-1 flex-col p-8">
        <div className="flex-1 text-center">
          <div className="bg-brand-500/10 text-brand-400 border-brand-500/20 mb-4 inline-block rounded-full border px-3 py-1 text-xs font-bold tracking-widest uppercase">
            {t("criticalQuestion")}
          </div>
          <h3 className="text-fg-primary text-fg-secondaryxl mb-4 font-extrabold">
            {localizedTitle}
          </h3>
          <p className="text-fg-secondary mb-8 text-sm leading-relaxed">{localizedDescription}</p>
        </div>

        <div className="space-y-6">
          {/* Professional Graph Bar */}
          <div className="space-y-2">
            <div className="flex justify-between px-1 text-xs font-medium">
              <span className="text-success-400 font-bold tracking-wider uppercase">
                {t("yes")}
              </span>
              <span className="text-fg-muted font-bold tracking-wider uppercase">
                {t("unsure")}
              </span>
              <span className="text-danger-400 font-bold tracking-wider uppercase">{t("no")}</span>
            </div>

            <div className="bg-bg-tertiary/40 border-border-subtle/50 relative flex h-8 w-full overflow-hidden rounded-md border">
              <div
                className="bg-success-500/90 group relative flex h-full items-center justify-start px-2 transition-all duration-1000 ease-out"
                style={{ width: `${yesPercent}%` }}
              >
                {yesPercent > 5 && (
                  <span className="text-xs font-bold text-white/90 drop-shadow-md">
                    %{yesPercent}
                  </span>
                )}
                <div className="absolute inset-0 bg-white/20 opacity-0 transition-opacity group-hover:opacity-100"></div>
              </div>
              <div
                className="bg-fg-muted/40 group relative flex h-full items-center justify-center transition-all duration-1000 ease-out"
                style={{ width: `${unsurePercent}%` }}
              >
                {unsurePercent > 5 && (
                  <span className="text-fg-secondary text-xs font-bold drop-shadow-md">
                    %{unsurePercent}
                  </span>
                )}
              </div>
              <div
                className="bg-danger-500/90 group relative flex h-full items-center justify-end px-2 transition-all duration-1000 ease-out"
                style={{ width: `${noPercent}%` }}
              >
                {noPercent > 5 && (
                  <span className="text-xs font-bold text-white/90 drop-shadow-md">
                    %{noPercent}
                  </span>
                )}
                <div className="absolute inset-0 bg-white/20 opacity-0 transition-opacity group-hover:opacity-100"></div>
              </div>
            </div>
            <div
              suppressHydrationWarning
              className="text-fg-muted pt-1 text-center text-xs font-medium"
            >
              {t("totalVotes", { count: totalVotes.toLocaleString() })}
            </div>
          </div>

          {/* Turnstile Widget (Invisible) */}
          {process.env.NODE_ENV === "production" && (
            <div className="flex flex-col items-center">
              <Turnstile
                ref={turnstileRef}
                key={turnstileKey}
                siteKey={process.env.NEXT_PUBLIC_TURNSTILE_SITE_KEY || "2x00000000000000000000AB"}
                onSuccess={(token) => {
                  setTurnstileToken(token);
                  setTurnstileError(false);
                  if (pendingVoteRef.current) {
                    executeVote(pendingVoteRef.current, token);
                  }
                }}
                onError={() => {
                  setTurnstileError(true);
                  console.warn("[Turnstile] Falling back to session token for voting.");
                }}
                onExpire={() => {
                  setTurnstileToken(null);
                }}
                options={{
                  theme: "dark",
                  size: "invisible",
                  execution: "execute",
                }}
              />
            </div>
          )}

          {/* Action buttons */}
          <div className="grid grid-cols-1 gap-3 pt-2 sm:grid-cols-3">
            <Button
              variant="outline"
              disabled={isVoting}
              onClick={() => handleVote("yes")}
              className={`w-full font-bold transition-all ${
                userChoice === "yes"
                  ? "border-success-400 bg-success-500/20 text-success-300 ring-success-400/40 ring-2"
                  : "text-success-400 border-success-400/40 hover:bg-success-400/20"
              }`}
            >
              {userChoice === "yes" && <Check className="mr-1 h-3.5 w-3.5" />}
              {t("yes")}
            </Button>
            <Button
              variant="outline"
              disabled={isVoting}
              onClick={() => handleVote("unsure")}
              className={`w-full font-bold transition-all ${
                userChoice === "unsure"
                  ? "border-fg-muted bg-fg-muted/20 text-fg-primary ring-fg-muted/40 ring-2"
                  : "text-fg-muted border-fg-muted/40 hover:bg-fg-muted/20"
              }`}
            >
              {userChoice === "unsure" && <Check className="mr-1 h-3.5 w-3.5" />}
              {t("unsureButton")}
            </Button>
            <Button
              variant="outline"
              disabled={isVoting}
              onClick={() => handleVote("no")}
              className={`w-full font-bold transition-all ${
                userChoice === "no"
                  ? "border-danger-400 bg-danger-500/20 text-danger-300 ring-danger-400/40 ring-2"
                  : "text-danger-400 border-danger-400/40 hover:bg-danger-400/20"
              }`}
            >
              {userChoice === "no" && <Check className="mr-1 h-3.5 w-3.5" />}
              {t("no")}
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { z } from "zod";

/**
 * TCSFL (Tactical Command & Synergy Flow Logic) AST/Regex Gate
 * Deterministik (Sıfır-LLM) doğrulama katmanı.
 * LLM token yakmadan önce kodun / verinin temel güvenlik ve şema sınırlarını denetler.
 */

export interface ValidationResult {
  isValid: boolean;
  errors: string[];
  astTrace?: unknown;
}

// Güvenlik kuralları ve yasaklı anahtar kelimeler
const FORBIDDEN_PATTERNS = [
  /eval\s*\(/i,
  /setTimeout\s*\(\s*['"]/i, // String execution in setTimeout
  /process\.env/i, // Hardcoded env access bypassing safe wrappers
];

/**
 * Hephaestus'tan gelen kod taslağını Regex/AST mantığıyla doğrular
 */
export function validateHephaestusOutput(codePayload: string): ValidationResult {
  const errors: string[] = [];

  // 1. Basic Syntax & Pattern Check (Zero-LLM Fast-Fail)
  if (!codePayload || codePayload.trim() === "") {
    return { isValid: false, errors: ["Empty payload received from Hephaestus."] };
  }

  // 2. Forbidden Pattern Analysis
  for (const pattern of FORBIDDEN_PATTERNS) {
    if (pattern.test(codePayload)) {
      errors.push(`Security violation: Detected forbidden pattern ${pattern.toString()}`);
    }
  }

  // 3. (Mock) AST Parsing Gate - In reality, uses acorn/tree-sitter bindings
  const hasSyntaxError = checkBasicBrackets(codePayload);
  if (hasSyntaxError) {
    errors.push("Syntax Error: Unmatched brackets or braces.");
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

/**
 * Extremely basic structural check for bracket matching (simulating AST step 1)
 */
function checkBasicBrackets(code: string): boolean {
  const stack = [];
  const map: Record<string, string> = { "}": "{", "]": "[", ")": "(" };
  for (const char of code) {
    if (char === "{" || char === "[" || char === "(") stack.push(char);
    else if (char === "}" || char === "]" || char === ")") {
      if (stack.pop() !== map[char]) return true; // Error
    }
  }
  return stack.length !== 0;
}

